import{_ as i,l,o as r,c as n,v as e,p as s,x as o,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const y=JSON.parse('{"title":"Gray 码","description":"","frontmatter":{"title":"Gray 码","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gray-code.md","filePath":"cs/gray-code.md","lastUpdated":1789023840000}'),h={name:"cs/gray-code.md"};function c(B,a,A,m,u,_){const t=l("Mermaid");return r(),n("div",null,[a[1]||(a[1]=e('<h1 id="gray-码" tabindex="-1">Gray 码 <a class="header-anchor" href="#gray-码" aria-label="Permalink to &quot;Gray 码&quot;">​</a></h1><div class="epigraph"><p>相邻的两个整数，在反射二进制里只翻一比特；自然二进制从 $0111$ 到 $1000$ 却同时翻四位。</p><footer>—— 据 Gray, Pulse Code Communication, U.S. Patent 2,632,058, 1953；Knuth, The Art of Computer Programming, Vol. 2 整理</footer></div><p>上一课<a href="/cs/positional-notation">进制与位权</a>钉死了：比特串加上基与位权才成为无符号整数，加法默认模 \\(2^n\\)。本课不重讲权怎么排，也不从「编码理论」另起。缺口是：自然二进制下，数值加一可以同时翻转很多位。机械盘、卡诺图相邻、后课异步接口，都怕这种「多位一起变」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>位权编码让电路对齐同一权再加，这是上一课的收获。计数、扫描、把连续角位移判成整数时，相邻两个值若汉明距离很大，采样落在中间会读出既不是旧值也不是新值的串。缺口因此不是新的基，而是另一种<strong>枚举次序</strong>：仍用 \\(n\\) 比特标 \\(\\{0,\\ldots,2^n-1\\}\\)，但相邻整数的码字只差一位。</p><p>反射二进制 Gray 码满足这条。它不是另一种位权：各位不再独立表示 \\(2^i\\)。算术仍在自然二进制里做；需要相邻只翻一位时，再换成 Gray。有符号还没有，本课整数仍无符号。</p><h3 id="gray-不是「把进位去掉」" tabindex="-1">Gray 不是「把进位去掉」 <a class="header-anchor" href="#gray-不是「把进位去掉」" aria-label="Permalink to &quot;Gray 不是「把进位去掉」&quot;">​</a></h3><p>模 \\(2^n\\) 加法照样进位，只是进位发生在二进制解释里。Gray 的相邻性是码表几何，不是加法器少了一根进位线。把两者混成「无进位二进制」，后课全加器会没有对象。</p><p><span class="marginnote">Gray 1953 的专利把反射二进制用于脉冲编码。Knuth Vol. 2 把位权系统写清楚之后，其余枚举都当成「同一整数的不同写法」。后课卡诺图的格子邻居，用的就是本课这条相邻。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记自然二进制为 \\(i\\)，一位 Gray 码 \\(G(i)=i\\oplus\\lfloor i/2\\rfloor\\)（逐位异或）。反变换：从最高位起，二进制位等于 Gray 位与已经恢复的更高位异或。本课不把异或提升成布尔公理——那是<a href="/cs/boolean-algebra">布尔代数</a>的缺口；这里只当比特上的可逆映射。</p>',11)),(r(),s(p,null,{default:o(()=>[E(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20UINT%5B%22%E6%97%A0%E7%AC%A6%E5%8F%B7%E4%BD%8D%E6%9D%83%22%5D%20--%3E%20BIN%5B%22%E8%87%AA%E7%84%B6%E4%BA%8C%E8%BF%9B%E5%88%B6%E8%AE%A1%E6%95%B0%22%5D%0A%20%20BIN%20--%3E%20MANY%5B%22%E5%8A%A0%E4%B8%80%E5%8F%AF%E8%83%BD%E7%BF%BB%E5%A4%9A%E4%BD%8D%22%5D%0A%20%20UINT%20--%3E%20GRAY%5B%22Gray%EF%BC%9A%E7%9B%B8%E9%82%BB%E5%8F%AA%E7%BF%BB%E4%B8%80%E4%BD%8D%22%5D%0A%20%20GRAY%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%A1%A5%E7%A0%81%E7%AE%97%E6%9C%AF%E4%BB%8D%E8%B5%B0%E4%BA%8C%E8%BF%9B%E5%88%B6%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>\\(n\\) 位 Gray 码正好 \\(2^n\\) 个，与上一课 \\(|\\Sigma^n|\\) 相同，只是相邻关系改了。循环意义上 \\(0\\) 与 \\(2^n-1\\) 也只差一位，构成一条哈密顿圈；本课不把图论请进来。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>转换是异或与移位，门数与 \\(n\\) 成正比，不改字宽。后课组合逻辑把最小项排进格雷码网格，几何相邻才等于差一个变量。旋转编码器输出 Gray，避免位置卡在进位边界时读出野码。这些都不取代位权：要做加减，先变回二进制。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入汉明距离的公理定义，只用「差几位」。纠错码的最小距离是<a href="/cs/hamming-distance">后课</a>。也不把 Gray 当成补码：下一课<a href="/cs/twos-complement">补码与溢出</a>仍在自然二进制的模 \\(2^n\\) 上取负。多位同时变的险象，要等组合电路课才命名。</p><p>后课默认：无符号算术用位权二进制；需要相邻只翻一位时，使用反射 Gray 码，再转换回来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自然二进制加一可翻多位；Gray 码让相邻整数只差一位。</li><li>Gray 不是位权，加减仍在二进制里做。</li><li>\\(G(i)=i\\oplus\\lfloor i/2\\rfloor\\) 可逆。</li><li>出处：Gray, 1953；Knuth, TAOCP Vol. 2 对同一整数不同写法的处理。</li></ul>',8))])}const G=i(h,[["render",c]]);export{y as __pageData,G as default};
